package org.apache.commons.lang3.text.translate;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class NumericEntityUnescaper_translate_TriageGen0Test {

    private NumericEntityUnescaper unescaper;
    private StringWriter out;

    @Before
    public void setUp() {
        unescaper = new NumericEntityUnescaper();
        out = new StringWriter();
    }









    @Test
    public void testTranslate_DecimalEntityLarge() throws IOException {
        // Testing entityValue > 0xFFFF
        // 0x10000 is 65536
        String input = "&#65536;";
        int result = unescaper.translate(input, 0, out);
        // 2 (&#) + 5 (65536) + 1 (;) = 8
        assertEquals(8, result);
        // Character.toChars(0x10000) returns two chars (surrogate pair)
        assertEquals(2, out.toString().length());
    }












}

