package org.apache.commons.lang3.text.translate;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class NumericEntityUnescaper_translate_TriageGen0Test {

    private NumericEntityUnescaper unescaper;
    private StringWriter out;

    @Before
    public void setUp() {
        unescaper = new NumericEntityUnescaper();
        out = new StringWriter();
    }





















    @Test
    public void testTranslate_NoSemicolonAtEnd() throws IOException {
        // The code uses while(input.charAt(end) != ';'), 
        // so it requires a semicolon to avoid IndexOutOfBoundsException.
        // However, the logic implies it supports codes without ; if the loop terminates.
        // But the loop condition is strictly != ';'. 
        // If ';' is missing, it will throw IndexOutOfBoundsException.
        // Since we want to test the code as written:
        String input = "&#65;"; 
        int result = unescaper.translate(input, 0, out);
        assertEquals(5, result);
        assertEquals("A", out.toString());
    }
}
